let LANG='en';
function gate(kind){
  gm.textContent=GATE[kind][LANG]||GATE[kind].en; gm.classList.add('on');
  openAcct('create');
}
function openAcct(v){scrim.classList.add('on');acct.classList.add('on');atab(v||'signin')}
function closeAcct(){scrim.classList.remove('on');acct.classList.remove('on');gm.classList.remove('on')}
function atab(v){
  ['signin','create','member'].forEach(n=>document.getElementById('v-'+n).classList.toggle('hidden',n!==v));
  const t=document.getElementById('atabs');t.style.display=v==='member'?'none':'flex';
  const b=t.querySelectorAll('button');b[0].classList.toggle('on',v==='signin');b[1].classList.toggle('on',v==='create');
  if(v==='member'){gm.classList.remove('on');document.getElementById('cartn').textContent='1'}
}
addEventListener('keydown',e=>{if(e.key==='Escape'){closeAcct();document.getElementById('drawer').classList.remove('open')}});

/* ---------- house storyline ---------- */
(function(){
  const items=[...document.querySelectorAll('.sl-item')];
  if(!items.length) return;
  const yr=document.getElementById('sl-year'), lb=document.getElementById('sl-label'), pg=document.getElementById('sl-progress');
  const media={};
  document.querySelectorAll('.sl-media-item').forEach(m=>media[m.dataset.year]=m);

  const STORYBOOK_WINDOW=200;
  let currentYear=null, activeStartY=0, ticking=false;

  function findActiveIndex(){
    const refY=window.innerHeight*0.4;
    let best=0, bestDist=Infinity;
    items.forEach((it,i)=>{
      const r=it.getBoundingClientRect();
      const dist=Math.abs((r.top+r.bottom)/2-refY);
      if(dist<bestDist){bestDist=dist;best=i;}
    });
    return best;
  }

  function setActive(idx){
    const it=items[idx];
    const year=it.dataset.year;
    if(year!==currentYear){
      items.forEach((el,i)=>{
        el.classList.toggle('on', i===idx);
        el.classList.toggle('past', i<idx);
      });
      yr.textContent=year;
      const key=it.dataset.labelKey;
      const h3=it.querySelector('h3');
      lb.textContent = h3 ? h3.textContent : '';
      lb.dataset.i = key;
      pg.style.height = ((idx+1)/items.length*100)+'%';
      Object.values(media).forEach(m=>m.classList.remove('on'));
      if(media[year]) media[year].classList.add('on');
      currentYear=year;
      activeStartY=window.scrollY;
    }
  }

  function updateStorybook(){
    if(!currentYear) return;
    const m=media[currentYear];
    if(!m) return;
    const frames=[...m.querySelectorAll('.mi')];
    if(frames.length<2) return;
    const progress=Math.min(1,Math.max(0,(window.scrollY-activeStartY)/STORYBOOK_WINDOW));
    const idx=Math.min(frames.length-1, Math.floor(progress*frames.length));
    frames.forEach((f,i)=>f.classList.toggle('show', i===idx));
  }

  function onScroll(){
    ticking=false;
    setActive(findActiveIndex());
    updateStorybook();
  }
  window.addEventListener('scroll',()=>{
    if(!ticking){ticking=true;setTimeout(onScroll,16);}
  },{passive:true});
  onScroll();
})();

/* ---------- markets ---------- */
function hi(m,on){document.querySelectorAll('[data-m="'+m+'"]').forEach(el=>el.classList.toggle('hi',on))}
document.querySelectorAll('.nd,.mlist li').forEach(el=>{
  el.addEventListener('mouseenter',()=>hi(el.dataset.m,true));
  el.addEventListener('mouseleave',()=>hi(el.dataset.m,el.dataset.m==='sg'));
});
document.querySelectorAll('.hexch,.crs').forEach(()=>{}); // noop guard placeholder
document.querySelectorAll('[data-count]').forEach(countEl=>{
  new IntersectionObserver((es,o)=>es.forEach(e=>{
    if(!e.isIntersecting)return;o.unobserve(e.target);
    const end=+e.target.dataset.count;let t0=null;
    const pre=e.target.dataset.prefix||'', suf=e.target.dataset.suffix||'';
    const tick=t=>{t0=t0||t;const k=Math.min((t-t0)/900,1);
      e.target.textContent=pre+Math.round(end*(1-Math.pow(1-k,3)))+suf;if(k<1)requestAnimationFrame(tick)};
    requestAnimationFrame(tick);
  }),{threshold:.6}).observe(countEl);
});

